let accessToken=null,currentUser=null;export function getAccessToken(){return accessToken}export async function getCurrentUser(){const e=await fetch("/api/session",{method:"GET",credentials:"include"});if(!e.ok){const{error:n}=await e.json();return JSON.stringify({error:"Failed to get user"})}return await e.json()}export async function login(e,n){const t=await fetch("/api/auth",{method:"POST",headers:{"Content-Type":"application/json"},credentials:"include",body:JSON.stringify({email:e,password:n})});return await t.json()}export async function logout(){const e=await fetch("/api/logout",{method:"POST",credentials:"include"});return await e.json()}export async function refresh(){const e=await fetch("/api/refresh",{method:"POST",credentials:"include"});if(!e.ok)return accessToken=null,currentUser=null,null;const n=await e.json();return accessToken=n.accessToken,accessToken}export async function initAuth(){return await refresh()}